        { let x = { let mut entries = Vec::new(); for (key, e) in self.variants.entries.iter() { let k = cx.str_out(*key); let x = Vehicle::ref_out((*e), cx, a); entries.push((k, x)); } a.map(entries) }; fields.push(("variants", x)); }
